// Compare each model answer with the expected answer (same criteria as the Python evaluators)
const cases = $('Load 20 test cases').all().map(i => i.json);
const outs = $input.all();
function findJsonText(o) {
  if (typeof o === 'string') return o.includes('hs_code') ? o : null;
  if (o && typeof o === 'object') { for (const v of Object.values(o)) { const t = findJsonText(v); if (t) return t; } }
  return null;
}
return outs.map((item, i) => {
  const c = cases[i];
  let a = {};
  const raw = findJsonText(item.json) || '{}';
  try { a = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { a = { parse_error: true }; }
  const code = String(a.hs_code || '').replace(/[^0-9]/g, '');
  const got = code.length >= 6 ? code.slice(0, 4) + '.' + code.slice(4, 6) : String(a.hs_code || '');
  const exp = c.expected_hs;
  const hs = exp.length === 0 ? null : (exp.includes(got) ? 1 : (exp.some(e => e.slice(0, 4) === got.slice(0, 4)) ? 0.5 : 0));
  const review = a.manual_review === true || a.manual_review === 'true';
  const falseAllClear = c.expected_review && !review;
  return { json: { id: c.id, expected_hs: exp.join(' / ') || '(ambiguous)', got_hs: got, hs_score: hs,
                   expected_review: c.expected_review, got_review: review, false_all_clear: falseAllClear,
                   description: c.description } };
});

// One summary line for the whole run
const rows = $input.all().map(i => i.json);
const scored = rows.filter(r => r.hs_score !== null);
const hsMean = scored.reduce((s, r) => s + r.hs_score, 0) / scored.length;
const fac = rows.filter(r => r.false_all_clear).map(r => r.id);
return [{ json: { cases: rows.length, hs_code_accuracy: Math.round(hsMean * 100) + '%',
                  false_all_clear: fac.length, false_all_clear_cases: fac.join(', ') || 'none',
                  wrong_codes: scored.filter(r => r.hs_score < 1).map(r => `${r.id}: ${r.got_hs} (expected ${r.expected_hs})`) } }];
